"use client";

import React, { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@hookform/resolvers/zod";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import EmailInput from "./EmailInput";
import PasswordInput from "./PasswordInput";
import ForgotPasswordDialog from "./ForgotPasswordDialog";
import SocialLoginButton from "./SocialLoginButton";
import { Link } from "react-router-dom";
import { useLoginMutation } from "@/hooks/mutations/use-auth-mutations";
import { completeTwoFactor } from "@/services/authService";
import { Input } from "@/components/ui/input";
import { dashboardPathFor } from "@/hooks/use-auth-session";
import { getUserErrorMessage } from "@domain/errors/app-error";
import { appAlert } from "@/presentation/lib/swal";
import { ArrowRight } from "lucide-react";
import PhoneInput from "../register/PhoneInput";
import { cn } from "@/lib/utils";

type LoginFormContentProps = {
  initialEmail?: string;
  onClose?: () => void;
};

const LOGIN_SAVED_KEY = "bibocom_login_identifier";

const isEmailValue = (value: string) =>
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());

const isPhoneValue = (value: string) =>
  /^\+?[0-9]{9,15}$/.test(value.replace(/\s/g, ""));

const isEmailOrPhone = (value: string) =>
  isEmailValue(value) || isPhoneValue(value);

// Schéma de validation pour email ou téléphone
const LoginFormSchema = z.object({
  login: z
    .string()
    .min(2, "Saisissez votre email ou votre téléphone")
    .refine((value) => isEmailOrPhone(value), {
      message: "Format invalide : email ou téléphone valide requis (ex : +221771234567)",
    }),
  password: z.string().min(1, "Le mot de passe est requis"),
  rememberMe: z.boolean().default(true),
});

const LoginFormContent: React.FC<LoginFormContentProps> = ({
  initialEmail = "",
  onClose,
}) => {
  const loginMutation = useLoginMutation();
  const isSubmitting = loginMutation.isPending;
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [resetIdentifier, setResetIdentifier] = useState("");
  const [loginError, setLoginError] = useState<string | null>(null);
  const [loginType, setLoginType] = useState<"email" | "phone">("phone");
  const [challenge, setChallenge] = useState<string | null>(null);
  const [otp, setOtp] = useState("");
  const [otpPending, setOtpPending] = useState(false);

  const form = useForm<z.infer<typeof LoginFormSchema>>({
    resolver: zodResolver(LoginFormSchema),
    defaultValues: {
      login: initialEmail,
      password: "",
      rememberMe: true,
    },
  });

  useEffect(() => {
    if (initialEmail) {
      form.setValue("login", initialEmail);
      setLoginType(isPhoneValue(initialEmail) ? "phone" : "email");
      return;
    }

    // Restaurer l'identifiant mémorisé via "Se souvenir de moi"
    const saved = localStorage.getItem(LOGIN_SAVED_KEY);
    if (saved) {
      form.setValue("login", saved);
      setLoginType(isPhoneValue(saved) ? "phone" : "email");
    }
  }, [initialEmail, form]);

  // Effacer l'erreur de connexion dès que l'utilisateur modifie ses identifiants
  const clearLoginError = () => {
    if (loginError) {
      setLoginError(null);
    }
  };

  const toggleLoginType = () => {
    setLoginType(loginType === "email" ? "phone" : "email");
    form.setValue("login", ""); // Réinitialiser la valeur quand on change le type
  };

  const onSubmit = async (values: z.infer<typeof LoginFormSchema>) => {
    try {
      // Préparer les données selon le format attendu par le backend
      const loginData = {
        password: values.password,
        email: "",
        phoneNumber: "",
      };

      // Ajouter email OU phoneNumber selon le type de connexion
      if (loginType === "email") {
        loginData.email = values.login;
        loginData.phoneNumber = undefined;
      } else {
        loginData.phoneNumber = values.login; // Déjà formaté avec le code pays par PhoneInput
        loginData.email = undefined;
      }

      console.log("📤 [LOGIN] Données envoyées:", loginData);

      const response = await loginMutation.mutateAsync(loginData);

      if (values.rememberMe) {
        localStorage.setItem(LOGIN_SAVED_KEY, values.login.trim());
      } else {
        localStorage.removeItem(LOGIN_SAVED_KEY);
      }

      if (response.requiresTwoFactor && response.challenge) {
        setChallenge(response.challenge);
        setLoginError(null);
        return;
      }
      if (!response.user) return;

      window.location.replace(dashboardPathFor(response.user.role));

      if (onClose) {
        onClose();
      }
    } catch (error) {
      const rawMessage = getUserErrorMessage(error);
      const errorMessage =
        rawMessage === "Numéro incorrect"
          ? "Aucun compte n'utilise ce numéro."
          : rawMessage === "Email incorrecte"
            ? "Aucun compte n'utilise cet email."
            : rawMessage;
      const isCredentialError =
        /mot de passe|identifiant|email|téléphone|telephone|numéro|numero|compte|incorrect|invalide|n'existe|introuvable|unauthorized|401/i.test(
          errorMessage
        );

      if (isCredentialError) {
        setLoginError(errorMessage);
      } else {
        await appAlert.error("Connexion impossible", errorMessage);
      }
    }
  };

  const submitOtp = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!challenge) return;
    setOtpPending(true);
    setLoginError(null);
    try {
      const session = await completeTwoFactor(challenge, otp.trim());
      window.location.replace(dashboardPathFor(session.user.role));
      onClose?.();
    } catch (error) {
      setLoginError(getUserErrorMessage(error));
    } finally {
      setOtpPending(false);
    }
  };

  const fieldClassName =
    "h-12 rounded-xl border-slate-200 bg-white shadow-none transition-all duration-300 focus-visible:ring-bibocom-primary/20 focus-visible:border-bibocom-primary";

  if (challenge) {
    return (
      <form onSubmit={submitOtp} className="space-y-5">
        <p className="text-sm text-slate-600">
          Saisissez le code à 6 chiffres de votre application d’authentification.
        </p>
        <Input
          inputMode="numeric"
          autoComplete="one-time-code"
          value={otp}
          onChange={(event) => setOtp(event.target.value)}
          placeholder="000000"
          className={fieldClassName}
        />
        {loginError ? <p className="text-sm text-bibocom-error">{loginError}</p> : null}
        <Button type="submit" disabled={otpPending || otp.trim().length < 6} className="h-12 w-full rounded-xl bg-bibocom-primary text-white">
          {otpPending ? "Vérification…" : "Valider le code"}
        </Button>
      </form>
    );
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-5">
        <FormField
          control={form.control}
          name="login"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-[13px] font-medium tracking-wide text-slate-600">
                {loginType === "email" ? "Email" : "Téléphone"}
              </FormLabel>
              <FormControl>
                {loginType === "phone" ? (
                  <PhoneInput
                    form={form}
                    field={{
                      ...field,
                      onChange: (value: string) => {
                        clearLoginError();
                        field.onChange(value);
                      },
                    }}
                  />
                ) : (
                  <EmailInput
                    {...field}
                    className={fieldClassName}
                    onChange={(event) => {
                      clearLoginError();
                      field.onChange(event);
                    }}
                  />
                )}
              </FormControl>
              <button
                type="button"
                onClick={toggleLoginType}
                className="text-xs font-medium text-slate-400 hover:text-bibocom-primary transition-colors duration-300"
              >
                {loginType === "email"
                  ? "Utiliser le téléphone"
                  : "Utiliser l'email"}
              </button>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="password"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-[13px] font-medium tracking-wide text-slate-600">
                Mot de passe
              </FormLabel>
              <FormControl>
                <PasswordInput
                  {...field}
                  className={fieldClassName}
                  onChange={(event) => {
                    clearLoginError();
                    field.onChange(event);
                  }}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        {loginError && (
          <p className="text-sm text-red-600">{loginError}</p>
        )}

        <div className="flex items-center justify-between">
          <FormField
            control={form.control}
            name="rememberMe"
            render={({ field }) => (
              <FormItem className="flex items-center space-x-2 space-y-0">
                <FormControl>
                  <Checkbox
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    className="rounded border-slate-300 data-[state=checked]:bg-bibocom-primary"
                  />
                </FormControl>
                <FormLabel className="text-sm font-normal text-slate-600">
                  Se souvenir de moi
                </FormLabel>
              </FormItem>
            )}
          />
          <button
            type="button"
            className="text-sm text-slate-500 hover:text-bibocom-primary transition-colors duration-300"
            onClick={() => {
              const currentLogin = form.getValues().login;
              setResetIdentifier(currentLogin || "");
              setShowForgotPassword(true);
            }}
          >
            Mot de passe oublié ?
          </button>
        </div>

        <Button
          type="submit"
          className={cn(
            "h-12 w-full rounded-xl bg-bibocom-primary text-white shadow-sm",
            "transition-all duration-300 hover:bg-[#081c30] hover:shadow-md hover:scale-[1.01]"
          )}
          disabled={isSubmitting}
        >
          {isSubmitting ? "Connexion en cours..." : "Se connecter"}
          {!isSubmitting && <ArrowRight className="h-4 w-4" />}
        </Button>

        <div className="relative py-1">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-slate-200"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="bg-white px-3 text-slate-400">
              Ou continuer avec
            </span>
          </div>
        </div>

        <SocialLoginButton
          provider="google"
          className="h-12 rounded-xl border-slate-200 text-slate-700 transition-all duration-300 hover:bg-slate-50 hover:border-slate-300"
        />

        {!onClose && (
          <p className="pt-2 text-sm text-slate-500">
            Pas encore de compte ?{" "}
            <Link
              to="/register"
              className="font-medium text-bibocom-primary transition-colors duration-300 hover:text-bibocom-accent"
            >
              S&apos;inscrire
            </Link>
          </p>
        )}
      </form>
      <ForgotPasswordDialog
        open={showForgotPassword}
        onOpenChange={setShowForgotPassword}
        resetIdentifier={resetIdentifier}
        setResetIdentifier={setResetIdentifier}
      />
    </Form>
  );
};
export default LoginFormContent;
